from pathlib import Path
import json,csv
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'results/V99_NUMERICAL_AUDIT_THEORY.json').read_text())
with open(ROOT/'inputs/V98_3D_TRAJECTORY.csv',encoding='utf-8-sig',newline='') as fp:
 r=list(csv.DictReader(fp))
points=[[float(v['x_mm']),float(v['y_mm']),float(v['z_um'])] for v in r[::2]]
hits=[{'x':a['radius_m']*1000*(-1 if a['k']%2 else 1),'y':0,'z':a['z_m']*1e6,'k':a['k']} for a in D['intersection_crosscheck'][-1]['intersections']]
html='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ROOT V99｜三维闭环自交审计</title><style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif}*{box-sizing:border-box}body{margin:0;background:#0a1020;color:#e2e8f0}header{padding:28px 4vw 12px}h1{font-size:clamp(22px,3vw,34px);margin:0 0 12px}p{color:#abc0d8;line-height:1.7;max-width:1000px}main{padding:10px 4vw 38px}.panel{background:#111d33;border:1px solid #31445d;border-radius:16px;padding:18px;margin-bottom:18px}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{background:#0b172b;padding:12px 16px;border-radius:10px;min-width:160px;flex:1}.stat b{display:block;color:#fff;font-size:20px;margin-top:5px}.controls{display:flex;flex-wrap:wrap;gap:22px;align-items:center;margin:12px 0}label{display:flex;align-items:center;gap:10px}input[type=range]{width:160px;accent-color:#38bdf8}canvas{width:100%;height:min(58vh,520px);background:#090f1c;border:1px solid #22374f;border-radius:12px;touch-action:none}small{color:#93a9c4}button{padding:9px 15px;border:1px solid #57718f;border-radius:9px;background:#17263b;color:white;cursor:pointer}.legend{color:#b6d2ea;font-size:13px;padding-top:8px}.dot{color:#ffb366}a{color:#75d2fc}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #293c52;font-size:14px}th{color:#90b4d8}@media(max-width:700px){.controls{display:block}.controls label{margin-bottom:14px}}
</style></head><body><header><small>ROOT V99 / THEORY, NOT EXPERIMENT / 2026-11-18</small><h1>三维周期轨道为什么不一定是空间结？</h1><p>模型：外部双线圈 Maxwell 场的电子数值轨道。橙色叉号是四组空间近自交点。下方可调节观察角度与<strong>人为</strong>轴向扰动；扰动图形不满足已知粒子方程，不能当作物理轨道。</p></header><main><div class="stats"><div class="stat">轨道类别<b>五圈三维周期候选</b></div><div class="stat">空间近自交<b>4 组</b></div><div class="stat">约化返回映射<b>tr≈2, det≈1</b></div><div class="stat">理论等级<b>非实验 / 未证四力统一</b></div></div><section class="panel"><div class="controls"><label>水平转角 <input type="range" id="yaw" min="-180" max="180" value="-25"><span id="yv">-25°</span></label><label>俯仰角 <input type="range" id="pitch" min="-80" max="80" value="45"><span id="pv">45°</span></label><label>人为 z 扰动 <input type="range" id="lift" min="-0.5" max="0.5" step="0.01" value="0"><span id="lv">0 µm</span></label><button id="reset">重置视图</button></div><canvas id="c" width="1200" height="660"></canvas><div class="legend">蓝线：V98 轨迹或人工扰动曲线 · <span class="dot">✕</span>：V98 对称自交位置 · z 方向为了看清被视觉放大 100 倍（绘图比例不反映真实 1:1 长度）。</div></section><section class="panel"><h2>关键的数学结论</h2><p>固定能量、正则角动量的轴对称哈密顿系统，若从 r、z 两个转折点出发并发生五圈完整周期回归，则 t 和 T−t 的径向、轴向坐标相同，方位角互为 10π 减去原角。由此在 φ=kπ (k=1,2,3,4) 必然出现不同时间的空间重合。若轨迹发生自交，普通结多项式不再有定义。</p><p>人为偏移 0.15 µm 的离散多边形，三种投影的 Fox 结行列式均为 9；这是数学示例，不是原物理轨道的结类型，也不是证明存在新相互作用。</p><h2>数值复核</h2><table><thead><tr><th>线圈求积阶数</th><th>四组空间近自交的最大距离</th><th>单周期端点返回残差</th></tr></thead><tbody id="rows"></tbody></table></section></main>
<script>
const points=__POINTS__,hits=__HITS__,data=__DATA__;
const $=id=>document.getElementById(id),canvas=$('c'),ctx=canvas.getContext('2d');
const rad=x=>x*Math.PI/180;
function project(p,yaw,pitch,shift){const x=p[0],y=p[1],z=(p[2]+shift)*.1;const Y=rad(yaw),P=rad(pitch);let a=x*Math.cos(Y)-y*Math.sin(Y),b=x*Math.sin(Y)+y*Math.cos(Y);return [a,(b*Math.sin(P)+z*Math.cos(P)),b*Math.cos(P)-z*Math.sin(P)];}
function draw(){const yaw=Number($('yaw').value),pitch=Number($('pitch').value),lift=Number($('lift').value);$('yv').textContent=yaw+'°';$('pv').textContent=pitch+'°';$('lv').textContent=lift.toFixed(2)+' µm';ctx.clearRect(0,0,canvas.width,canvas.height);let pp=points.map((p,i)=>project(p,yaw,pitch,lift*Math.sin(i/(points.length-1)*Math.PI*2))),xx=pp.map(x=>x[0]),yy=pp.map(x=>x[1]);let range=Math.max(Math.max(...xx)-Math.min(...xx),Math.max(...yy)-Math.min(...yy),.1),scale=480/range,xc=(Math.max(...xx)+Math.min(...xx))/2,yc=(Math.max(...yy)+Math.min(...yy))/2;const position=p=>[600+(p[0]-xc)*scale,330-(p[1]-yc)*scale];ctx.strokeStyle='#3ea4d8';ctx.lineWidth=2.5;ctx.beginPath();pp.forEach((p,i)=>{let [x,y]=position(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.stroke();
if(Math.abs(lift)<.001){ctx.fillStyle='#ffb366';ctx.font='bold 18px system-ui';hits.forEach(h=>{let [x,y]=position(project([h.x,h.y,h.z],yaw,pitch,0));ctx.fillText('✕',x-8,y+6);});}ctx.fillStyle='#9eb5cd';ctx.font='16px system-ui';ctx.fillText('可旋转视图 / 理论轨迹 / 非实验观测',20,30)}
['yaw','pitch','lift'].forEach(x=>$(x).addEventListener('input',draw));$('reset').addEventListener('click',()=>{$('yaw').value=-25;$('pitch').value=45;$('lift').value=0;draw()});
$('rows').innerHTML=data.intersection_crosscheck.map(x=>'<tr><td>'+x.order+'</td><td>'+Math.max(...x.intersections.map(v=>v.separation_m)).toExponential(3)+' m</td><td>'+x.return_position_m.toExponential(3)+' m</td></tr>').join('');draw();
</script></body></html>'''
html=html.replace('__POINTS__',json.dumps(points,separators=(',',':'))).replace('__HITS__',json.dumps(hits,separators=(',',':'))).replace('__DATA__',json.dumps({'intersection_crosscheck':D['intersection_crosscheck']},separators=(',',':')))
(ROOT/'web/index.html').write_text(html,encoding='utf-8')
print('Offline viewer',len(points),'points',len(html),'bytes')
